const book = {
  title: "Eloquent JavaScript",
  pages: 472,
  available: true,
};

console.log(book.title);
console.log(book["pages"]);

const key = "available";
console.log(book[key]);        // the key comes from a variable

book.year = 2024;              // add a property
book.pages = 480;              // change one
delete book.available;         // remove one
console.log(Object.keys(book).join(", "));

const order = {
  id: 1001,
  customer: { name: "Grace", address: { city: "Paris" } },
  items: ["keyboard", "mouse"],
};

console.log(order.customer.address.city);
console.log(order.items[1]);
console.log(order.customer.phone);
console.log(order.customer.phone?.number);
console.log(order.customer.phone?.number ?? "no phone on file");
console.log("customer" in order);

const account = {
  owner: "Ada",
  balance: 100,
  deposit(amount) {
    this.balance += amount;
    return this.balance;
  },
  describe() {
    return `${this.owner} has ${this.balance} credits`;
  },
};

account.deposit(50);
console.log(account.describe());
console.log(typeof account.deposit);

const stock = { apples: 3, pears: 0, plums: 12 };

console.log(Object.keys(stock).join(", "));
console.log(Object.values(stock).join(", "));

for (const [name, count] of Object.entries(stock)) {
  if (count === 0) continue;
  console.log(`${name}: ${count}`);
}

const total = Object.values(stock).reduce((sum, n) => sum + n, 0);
console.log(total);

const original = { theme: "dark", fontSize: 14 };
const alias = original;
const copy = { ...original };

alias.fontSize = 16;
console.log(original.fontSize);   // changed through the alias
console.log(copy.fontSize);       // the copy is independent

console.log(original === alias);  // same object
console.log(original === copy);   // different objects, even if contents matched
console.log(JSON.stringify(copy));

function createButton(options) {
  const settings = { label: "OK", size: "medium", disabled: false, ...options };
  return `${settings.label} (${settings.size}${settings.disabled ? ", disabled" : ""})`;
}

console.log(createButton({ label: "Save" }));
console.log(createButton({ size: "large", disabled: true }));
